export interface CruiseState { held: boolean; allowed: boolean; }
let state: CruiseState = { held: false, allowed: false };
const listeners = new Set<(s: CruiseState) => void>();
export function setCruiseState(next: CruiseState): void { // emit on change
  if (next.held === state.held && next.allowed === state.allowed) return;
  state = next; for (const l of listeners) l(next);
}
export function cruiseState(): CruiseState
